CREATE TABLE IF NOT EXISTS utenti (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, creato INTEGER NOT NULL, consenso INTEGER NOT NULL, promemoria INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS link_accesso (hash TEXT PRIMARY KEY, email TEXT NOT NULL, scade INTEGER NOT NULL, consenso INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessioni (hash TEXT PRIMARY KEY, utente_id INTEGER NOT NULL, scade INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS preferiti (utente_id INTEGER NOT NULL, bene_id TEXT NOT NULL, dati TEXT NOT NULL, aggiunto INTEGER NOT NULL, PRIMARY KEY (utente_id, bene_id));
CREATE TABLE IF NOT EXISTS inviati (utente_id INTEGER NOT NULL, bene_id TEXT NOT NULL, soglia INTEGER NOT NULL, quando INTEGER NOT NULL, PRIMARY KEY (utente_id, bene_id, soglia));
CREATE TABLE IF NOT EXISTS limiti (chiave TEXT NOT NULL, finestra INTEGER NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (chiave, finestra));
